insert into memories(id,destination_id,title,subtitle,story,memory_date,visibility) values ('00000000-0000-0000-0000-000000000030','00000000-0000-0000-0000-000000000020','The night we found Paris.','A warm August evening, kept close.','We reached the Eiffel Tower just before sunset, with no plan beyond following the light. The city felt less like a landmark and more like a secret we had been invited to keep.\n\nWe walked until our feet hurt, stopped for bread and cold water beside the Seine, and watched Paris turn gold. It was the kind of evening that asks nothing from you except that you remember it.','2026-08-21','PUBLIC');
