insert into timeline_events(memory_id,title,description,event_time,sort_order) values ('00000000-0000-0000-0000-000000000030','Breakfast at the corner café','Coffee, a croissant, and the beginning of a long day.','09:00',1),('00000000-0000-0000-0000-000000000030','Louvre','We followed the rooms with no map.','11:30',2),('00000000-0000-0000-0000-000000000030','Eiffel Tower','The sky turned peach above the ironwork.','17:45',3),('00000000-0000-0000-0000-000000000030','The Seine','A final walk while the city came alive.','21:30',4);
